"""Wrap deploy/monitoring/prometheus/alerts.yml in a PrometheusRule CRD.

Keeps one source of truth for alert rules across docker-compose, the bundled
Kubernetes Prometheus and kube-prometheus-stack.
"""

from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SRC = ROOT / "deploy/monitoring/prometheus/alerts.yml"
DST = ROOT / "deploy/k8s/extras/prometheusrule.yaml"

HEADER = """\
# GENERATED by `make prometheusrule` from deploy/monitoring/prometheus/alerts.yml - do not edit.
apiVersion: monitoring.coreos.com/v1
kind: PrometheusRule
metadata:
  name: finguard-alerts
  namespace: finguard
  labels:
    release: kube-prometheus-stack
spec:
"""

body = "".join(f"  {line}" if line.strip() else line for line in SRC.read_text().splitlines(keepends=True))
DST.write_text(HEADER + body)
print(f"wrote {DST.relative_to(ROOT)}")
